scan_linter_check.script:
(function(engine) {
    var kind = new global.EcsContext(engine.current).clientKind();
    if (!engine.rootNode || !kind) {
        return;
    }
    var hits = new global.EcsClientScript(new global.EcsAst(engine.rootNode), kind).synchronousCalls();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CLIENT-001',
        title: 'Synchronous server call in a client-side script',
        recommendation: 'Use an asynchronous call with a callback: GlideAjax getXMLAnswer(callback) or ' +
            'getXML(callback), g_form.getReference(field, callback), or GlideRecord query(callback). ' +
            'Synchronous calls freeze the form, and getXMLWait() is not available in Service Portal.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
